/**
 * Mushroom Weather Station Card
 * Home Assistant Lovelace custom card — HACS plugin
 * Version 0.1.0
 *
 * type: custom:mushroom-weather-station-card
 */
const CARD_VERSION = "0.1.0";
const CARD_TYPE = "mushroom-weather-station-card";
const CARD_NAME = "Mushroom Weather Station Card";

const PREFIX_MAP = {
  temperature: "sensor.{p}_temperature",
  feels_like: "sensor.{p}_feels_like",
  humidity: "sensor.{p}_humidity",
  dew_point: "sensor.{p}_dew_point",
  wind_speed: "sensor.{p}_wind_speed",
  wind_gust: "sensor.{p}_wind_gust",
  max_gust: "sensor.{p}_max_gust",
  wind_direction: "sensor.{p}_wind_direction",
  rain_rate: "sensor.{p}_precipitation_intensity",
  rain_today: "sensor.{p}_daily_rain",
  rain_event: "sensor.{p}_event_rain",
  rain_week: "sensor.{p}_weekly_rain",
  rain_month: "sensor.{p}_monthly_rain",
  rain_year: "sensor.{p}_yearly_rain",
  last_rain: "sensor.{p}_last_rain",
  uv: "sensor.{p}_uv_index",
  irradiance: "sensor.{p}_irradiance",
  illuminance: "sensor.{p}_solar_rad_lx",
  battery: "binary_sensor.{p}_battery",
};

const CARDINALS = ["N","NNE","NE","ENE","E","ESE","SE","SSE","S","SSW","SW","WSW","W","WNW","NW","NNW"];
const CARDINAL_ICON = {N:"mdi:arrow-up-bold",NNE:"mdi:arrow-top-right-bold",NE:"mdi:arrow-top-right-bold",ENE:"mdi:arrow-right-bold",E:"mdi:arrow-right-bold",ESE:"mdi:arrow-bottom-right-bold",SE:"mdi:arrow-bottom-right-bold",SSE:"mdi:arrow-down-bold",S:"mdi:arrow-down-bold",SSW:"mdi:arrow-bottom-left-bold",SW:"mdi:arrow-bottom-left-bold",WSW:"mdi:arrow-left-bold",W:"mdi:arrow-left-bold",WNW:"mdi:arrow-top-left-bold",NW:"mdi:arrow-top-left-bold",NNW:"mdi:arrow-up-bold"};

function degToCardinal(deg){const n=Number(deg);if(!Number.isFinite(n))return null;return CARDINALS[Math.round((((n%360)+360)%360)/22.5)%16];}
function num(state){if(state==null||state==="unknown"||state==="unavailable"||state==="")return null;const n=parseFloat(state);return Number.isFinite(n)?n:null;}
function fmtNum(n,digits=1){if(n==null)return "—";return Number(n).toFixed(digits).replace(/\.0$/, "");}
function tempColor(t){if(t==null)return"grey";if(t>=115)return"purple";if(t>=105)return"red";if(t>=95)return"orange";if(t>=80)return"amber";if(t>=60)return"green";return"blue";}
function uvMeta(uv){if(uv==null)return{label:"—",color:"grey"};if(uv>=11)return{label:"Extreme",color:"purple"};if(uv>=8)return{label:"Very high",color:"red"};if(uv>=6)return{label:"High",color:"orange"};if(uv>=3)return{label:"Moderate",color:"amber"};return{label:"Low",color:"green"};}
function applyPrefix(config){const prefix=(config.prefix||"").trim().replace(/^sensor\./,"").replace(/_+$/,"");if(!prefix)return{...config};const entities={...(config.entities||{})};for(const [key,template] of Object.entries(PREFIX_MAP)){if(!entities[key])entities[key]=template.replace("{p}",prefix);}return{...config,entities};}
function entityState(hass,entityId){if(!hass||!entityId)return null;return hass.states[entityId]||null;}
function unitOf(st){return st?.attributes?.unit_of_measurement||"";}
function formatLastRain(st,hass){const raw=st?.state;if(!raw||raw==="unknown"||raw==="unavailable")return"—";const date=new Date(raw);if(Number.isNaN(date.getTime()))return raw;try{return new Intl.DateTimeFormat(hass?.locale?.language||undefined,{month:"numeric",day:"numeric",hour:"numeric",minute:"2-digit"}).format(date);}catch(_e){return date.toLocaleString();}}

class MushroomWeatherStationCard extends HTMLElement{
  static getStubConfig(){return{prefix:"ws",layout:"full",name:"Weather Station"};}
  static async getConfigElement(){return document.createElement(`${CARD_TYPE}-editor`);}
  setConfig(config){if(!config)throw new Error("Invalid configuration");this._config=applyPrefix({layout:"full",name:"Weather Station",entities:{},...config});this._render();}
  set hass(hass){this._hass=hass;this._render();} get hass(){return this._hass;}
  getCardSize(){const layout=this._config?.layout||"full";if(layout==="chips")return 1;if(layout==="compact")return 3;return 7;}
  getGridOptions(){const layout=this._config?.layout||"full";if(layout==="chips")return{columns:12,rows:1};if(layout==="compact")return{columns:12,rows:3};return{columns:12,rows:6};}
  _st(key){return entityState(this._hass,this._config?.entities?.[key]);}
  _moreInfo(entityId){if(!entityId)return;this.dispatchEvent(new CustomEvent("hass-more-info",{bubbles:true,composed:true,detail:{entityId}}));}
  _esc(s){return String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;");}
  _tile(label,st,value,icon,color){if(!st&&!this._config.show_empty)return"";const entityId=st?.entity_id||"";return `<button class="tile" data-entity="${this._esc(entityId)}" ${entityId?"":"disabled"}><ha-icon icon="${icon}" class="${color||"grey"}"></ha-icon><div class="tile-value">${this._esc(String(value))}</div><div class="tile-label">${this._esc(label)}</div></button>`;}
  _chips(temp,feels,humidity,today,wind,raining){const chips=[{st:temp,icon:"mdi:thermometer",text:num(temp?.state)==null?"—":`${Math.round(num(temp?.state))}°`},{st:feels,icon:"mdi:sun-thermometer",text:num(feels?.state)==null?"—":`${Math.round(num(feels?.state))}°`},{st:humidity,icon:"mdi:water-percent",text:num(humidity?.state)==null?"—":`${Math.round(num(humidity?.state))}%`},{st:today,icon:raining?"mdi:weather-pouring":"mdi:weather-rainy",text:`${fmtNum(num(today?.state),2)} in`},{st:wind,icon:"mdi:weather-windy",text:`${fmtNum(num(wind?.state),0)} mph`}].filter(c=>c.st);return `<div class="chips">${chips.map(c=>`<button class="chip" data-entity="${this._esc(c.st.entity_id)}"><ha-icon icon="${c.icon}"></ha-icon><span>${this._esc(c.text)}</span></button>`).join("")}</div>`;}
  _render(){if(!this._config)return;if(!this.shadowRoot)this.attachShadow({mode:"open"});const layout=this._config.layout||"full";const name=this._config.name||"Weather Station";const hass=this._hass;const temp=this._st("temperature");const feels=this._st("feels_like");const humidity=this._st("humidity");const dew=this._st("dew_point");const wind=this._st("wind_speed");const gust=this._st("wind_gust");const maxGust=this._st("max_gust");const wdir=this._st("wind_direction");const rate=this._st("rain_rate");const today=this._st("rain_today");const event=this._st("rain_event");const week=this._st("rain_week");const month=this._st("rain_month");const year=this._st("rain_year");const lastRain=this._st("last_rain");const uv=this._st("uv");const irr=this._st("irradiance");const lux=this._st("illuminance");const battery=this._st("battery");const t=num(temp?.state);const f=num(feels?.state);const h=num(humidity?.state);const d=num(dew?.state);const ws=num(wind?.state);const wg=num(gust?.state);const deg=num(wdir?.state);const card=degToCardinal(deg);const rr=num(rate?.state);const uvn=num(uv?.state);const raining=rr!=null&&rr>0;const uvm=uvMeta(uvn);const heroIcon=raining?(rr>=0.3?"mdi:weather-pouring":"mdi:weather-rainy"):(uvn!=null&&uvn>=6?"mdi:weather-sunny":(uvn!=null&&uvn>=1?"mdi:weather-partly-cloudy":"mdi:weather-night"));const missing=!temp&&!this._config.entities?.temperature;this.shadowRoot.innerHTML=`<style>${MushroomWeatherStationCard.styles}</style><ha-card>${layout==="chips"?this._chips(temp,feels,humidity,today,wind,raining):""}${layout!=="chips"?`<div class="header"><div class="title">${this._esc(name)}</div><div class="subtitle">${raining?`Raining · ${fmtNum(rr,2)} ${this._esc(unitOf(rate)||"in/h")}`:"Station"}</div></div><button class="hero" data-entity="${this._esc(temp?.entity_id||"")}"><ha-icon icon="${heroIcon}" class="hero-icon ${tempColor(t)}"></ha-icon><div class="hero-text"><div class="hero-primary">${t==null?"—":Math.round(t)}°</div><div class="hero-secondary">${f!=null?`feels ${Math.round(f)}°`:""}${h!=null?` · ${Math.round(h)}% rh`:""}</div></div></button><div class="grid">${this._tile("Outdoor",temp,t==null?"—":`${fmtNum(t,1)}°`,"mdi:thermometer",tempColor(t))}${this._tile("Feels like",feels,f==null?"—":`${fmtNum(f,1)}°`,"mdi:sun-thermometer-outline",tempColor(f))}${this._tile("Humidity",humidity,h==null?"—":`${Math.round(h)}%`,"mdi:water-percent",h!=null&&h>=50?"cyan":"blue")}${this._tile("Dew point",dew,d==null?"—":`${fmtNum(d,1)}°`,"mdi:molecule",d!=null&&d>=70?"red":d!=null&&d>=60?"orange":"blue")}</div>`:""}${layout==="full"?`<div class="section-label">Wind</div><div class="grid">${this._tile("Speed",wind,ws==null?"—":`${fmtNum(ws,1)} ${this._esc(unitOf(wind)||"mph")}`,"mdi:weather-windy",ws!=null&&ws>=20?"orange":"teal")}${this._tile("Gust",gust,wg==null?"—":`${fmtNum(wg,1)}`,"mdi:windsock",wg!=null&&wg>=25?"orange":"teal")}${this._tile("Max gust",maxGust,num(maxGust?.state)==null?"—":`${fmtNum(num(maxGust?.state),1)}`,"mdi:weather-windy-variant","teal")}${this._tile(card||"Dir",wdir,deg==null?"—":`${Math.round(deg)}°`,CARDINAL_ICON[card]||"mdi:compass-outline","teal")}</div><div class="section-label">Rain</div><div class="grid">${this._tile("Rate",rate,rr==null?"—":`${fmtNum(rr,2)}`,"mdi:weather-rainy",raining?"blue":"grey")}${this._tile("Today",today,num(today?.state)==null?"—":`${fmtNum(num(today?.state),2)} in`,"mdi:cup-water",num(today?.state)>0?"cyan":"grey")}${this._tile("Event",event,num(event?.state)==null?"—":`${fmtNum(num(event?.state),2)} in`,"mdi:weather-pouring",num(event?.state)>0?"blue":"grey")}${this._tile("Week",week,num(week?.state)==null?"—":`${fmtNum(num(week?.state),2)} in`,"mdi:calendar-week",num(week?.state)>0?"blue":"grey")}${this._tile("Month",month,num(month?.state)==null?"—":`${fmtNum(num(month?.state),2)} in`,"mdi:calendar-month",num(month?.state)>0?"blue":"grey")}${this._tile("Year",year,num(year?.state)==null?"—":`${fmtNum(num(year?.state),2)} in`,"mdi:calendar-star",num(year?.state)>0?"blue":"grey")}${this._tile("Last rain",lastRain,formatLastRain(lastRain,hass),"mdi:clock-outline","blue")}</div><div class="section-label">Sun</div><div class="grid">${this._tile(uvm.label,uv,uvn==null?"—":`${fmtNum(uvn,0)}`,"mdi:weather-sunny-alert",uvm.color)}${this._tile("Solar",irr,num(irr?.state)==null?"—":`${fmtNum(num(irr?.state),0)} ${this._esc(unitOf(irr))}`,"mdi:solar-power-variant","amber")}${this._tile("Light",lux,num(lux?.state)==null?"—":`${fmtNum(num(lux?.state),0)} lx`,"mdi:brightness-5","amber")}</div>${battery?`<div class="battery ${battery.state==="on"?"warn":"ok"}"><ha-icon icon="${battery.state==="on"?"mdi:battery-alert":"mdi:battery"}"></ha-icon>${battery.state==="on"?"Station battery low":"Station battery OK"}</div>`:""}`:""}${missing&&hass?`<div class="hint">Set <code>prefix</code> (e.g. <code>ws</code>) or pick entities in the card editor.</div>`:""}</ha-card>`;this.shadowRoot.querySelectorAll("[data-entity]").forEach(el=>{el.addEventListener("click",()=>this._moreInfo(el.dataset.entity));});}
  static get styles(){return `:host{display:block}ha-card{padding:12px 12px 8px;background:var(--ha-card-background,var(--card-background-color))}.header{padding:4px 4px 8px}.title{font-weight:600;font-size:16px;color:var(--primary-text-color)}.subtitle{font-size:13px;color:var(--secondary-text-color);margin-top:2px}.hero{display:flex;align-items:center;gap:12px;width:100%;border:0;background:transparent;color:inherit;text-align:left;padding:4px 4px 12px;cursor:pointer}.hero-icon{--mdc-icon-size:36px}.hero-primary{font-size:32px;font-weight:600;line-height:1.1}.hero-secondary{font-size:13px;color:var(--secondary-text-color)}.section-label{font-size:14px;font-weight:600;padding:10px 4px 6px;color:var(--primary-text-color)}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.tile{display:flex;flex-direction:column;align-items:center;gap:4px;border:0;background:var(--secondary-background-color,rgba(0,0,0,.08));border-radius:12px;padding:10px 4px 8px;color:inherit;cursor:pointer;min-height:88px}.tile[disabled]{opacity:.45;cursor:default}.tile ha-icon{--mdc-icon-size:22px}.tile-value{font-weight:600;font-size:14px;text-align:center}.tile-label{font-size:11px;color:var(--secondary-text-color);text-align:center}.chips{display:flex;flex-wrap:wrap;gap:8px;padding:4px}.chip{display:inline-flex;align-items:center;gap:6px;border:0;border-radius:18px;padding:6px 10px;background:var(--secondary-background-color,rgba(0,0,0,.08));color:inherit;cursor:pointer;font-size:13px}.chip ha-icon{--mdc-icon-size:18px}.battery{display:flex;align-items:center;gap:8px;font-size:13px;padding:10px 6px 6px}.battery.ok{color:var(--success-color,#4caf50)}.battery.warn{color:var(--error-color,#f44336)}.hint{font-size:12px;color:var(--secondary-text-color);padding:8px 4px}.purple{color:var(--purple-color,#9c27b0)}.red{color:var(--red-color,#f44336)}.orange{color:var(--orange-color,#ff9800)}.amber{color:var(--amber-color,#ffc107)}.green{color:var(--green-color,#4caf50)}.blue{color:var(--blue-color,#2196f3)}.cyan{color:var(--cyan-color,#00bcd4)}.teal{color:var(--teal-color,#009688)}.grey{color:var(--disabled-text-color,#9e9e9e)}@media(max-width:420px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}`;}
}

class MushroomWeatherStationCardEditor extends HTMLElement{
  setConfig(config){this._config={entities:{},...config};this._render();}
  set hass(hass){this._hass=hass;}
  _fire(config){this._config=config;this.dispatchEvent(new CustomEvent("config-changed",{detail:{config},bubbles:true,composed:true}));this._render();}
  _onInput(e){const target=e.target;const key=target.dataset.key;const section=target.dataset.section;const value=target.type==="checkbox"?target.checked:target.value;const next={...this._config,entities:{...(this._config.entities||{})}};if(section==="entities"){if(value)next.entities[key]=value;else delete next.entities[key];}else{next[key]=value;}if(key==="prefix")Object.assign(next,applyPrefix(next));this._fire(next);}
  _esc(s){return String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;");}
  _render(){if(!this._config)return;if(!this.shadowRoot)this.attachShadow({mode:"open"});const c=this._config;const e=c.entities||{};const fields=[["temperature","Temperature"],["feels_like","Feels like"],["humidity","Humidity"],["dew_point","Dew point"],["wind_speed","Wind speed"],["wind_gust","Wind gust"],["max_gust","Max gust"],["wind_direction","Wind direction (°)"],["rain_rate","Rain rate"],["rain_today","Rain today"],["rain_event","Rain event"],["rain_week","Rain week"],["rain_month","Rain month"],["rain_year","Rain year"],["last_rain","Last rain"],["uv","UV index"],["irradiance","Solar / irradiance"],["illuminance","Illuminance"],["battery","Battery (binary)"]];this.shadowRoot.innerHTML=`<style>.wrap{padding:4px 0 16px;display:grid;gap:10px}label{display:grid;gap:4px;font-size:13px;color:var(--primary-text-color)}input,select{width:100%;box-sizing:border-box;padding:8px 10px;border-radius:8px;border:1px solid var(--divider-color);background:var(--card-background-color);color:var(--primary-text-color)}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.help{font-size:12px;color:var(--secondary-text-color)}h3{margin:12px 0 0;font-size:14px}</style><div class="wrap"><label>Name<input data-key="name" value="${this._esc(c.name||"")}" placeholder="Weather Station" /></label><div class="row"><label>Layout<select data-key="layout"><option value="full" ${c.layout==="full"||!c.layout?"selected":""}>Full station</option><option value="compact" ${c.layout==="compact"?"selected":""}>Compact</option><option value="chips" ${c.layout==="chips"?"selected":""}>Chips strip</option></select></label><label>Entity prefix<input data-key="prefix" value="${this._esc(c.prefix||"")}" placeholder="ws" /></label></div><div class="help">Prefix <code>ws</code> auto-fills Ecowitt-style entity IDs. Override below.</div><h3>Entities</h3>${fields.map(([key,label])=>`<label>${label}<input data-section="entities" data-key="${key}" value="${this._esc(e[key]||"")}" placeholder="sensor.…" /></label>`).join("")}</div>`;this.shadowRoot.querySelectorAll("input, select").forEach(el=>{el.addEventListener("change",ev=>this._onInput(ev));});}
}

customElements.define(CARD_TYPE, MushroomWeatherStationCard);
customElements.define(`${CARD_TYPE}-editor`, MushroomWeatherStationCardEditor);
window.customCards = window.customCards || [];
window.customCards.push({type:CARD_TYPE,name:CARD_NAME,description:"Mushroom-style weather station card for Ecowitt / personal WS sensors.",preview:true,documentationURL:"https://github.com/highergroundstudio/lovelace-mushroom-weather-station-card"});
console.info(`%c ${CARD_NAME} %c ${CARD_VERSION} `,"color:#fff;background:#1b4d3e;font-weight:bold;padding:2px 6px;","color:#1b4d3e;background:#e8f5e9;font-weight:bold;padding:2px 6px;");
